// Charts, AS GRAPH SOURCE (#3690, epic #3604) — the @/shared/ui/charts barrel (LineArea/Bars/Donut/
// StatCard/TelemetryPanel/… 17 exports) as DATA, its 3 CTX-free source files concatenated. provides
// @/shared/ui/charts; deps (format.loginColor, Skeleton, FillBar) stay registered/graph.
import { useState, useCallback, type ReactNode, type CSSProperties } from "react";
import { loginColor } from "@/shared/lib/core/format";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { FillBar } from "@/shared/ui/data/FillBar";
import { Avatar } from "@/shared/ui/data/Avatar";
// Shared analytics chart primitives (#399), ported from
// design/fleet-github-skills/js/charts.jsx. On-brand viewBox-based SVG charts
// tuned to the token system, with optional hover tooltips (see useTip). Used by
// the Fleet and (later) Repo Pulse analytics pages.

/** Hover-tooltip controller handle (see {@link useTip}). */
export interface ChartTip {
  show: (x: number, y: number, content: ReactNode) => void;
  hide: () => void;
}

// ── multi-series line / area ────────────────────────────────────────────────
export interface LineSeries {
  name: string;
  color: string;
  data: number[];
  width?: number;
  dash?: string;
  dots?: boolean;
  fill?: boolean;
  dotR?: number;
}
interface LineAreaProps {
  series: LineSeries[];
  labels: string[];
  height?: number;
  yMax?: number;
  area?: boolean;
  fmtY?: (v: number) => ReactNode;
  tip?: ChartTip;
}
export function LineArea({ series, labels, height = 150, yMax, area = true, fmtY = (v) => v, tip }: LineAreaProps) {
  const W = 720, H = height, PAD = { l: 34, r: 14, t: 12, b: 22 };
  const iw = W - PAD.l - PAD.r, ih = H - PAD.t - PAD.b;
  const n = labels.length;
  const max = yMax ?? Math.max(1, ...series.flatMap(s => s.data));
  const x = (i: number) => PAD.l + (n <= 1 ? iw / 2 : (i / (n - 1)) * iw);
  const y = (v: number) => PAD.t + (1 - v / max) * ih;
  const yTicks = [0, 0.25, 0.5, 0.75, 1].map(t => Math.round(max * t));
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", display: "block" }} onMouseLeave={() => tip?.hide()}>
      {yTicks.map((v, i) => (
        <g key={i}>
          <line x1={PAD.l} y1={y(v)} x2={W - PAD.r} y2={y(v)} stroke="var(--border-soft)" strokeDasharray="2 3" />
          <text x={PAD.l - 5} y={y(v) + 3} textAnchor="end" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{fmtY(v)}</text>
        </g>
      ))}
      {labels.map((l, i) => i % Math.ceil(n / 8 || 1) === 0 && (
        <text key={i} x={x(i)} y={H - PAD.b + 13} textAnchor="middle" fontFamily="var(--mono)" fontSize="8.5" fill="var(--fg-dim)">{l}</text>
      ))}
      {series.map((s, si) => {
        const line = s.data.map((v, i) => `${i === 0 ? "M" : "L"} ${x(i)} ${y(v)}`).join(" ");
        const fillPath = `${line} L ${x(n - 1)} ${y(0)} L ${x(0)} ${y(0)} Z`;
        const show = (e: React.MouseEvent, i: number) =>
          tip?.show(e.clientX, e.clientY, <span><b style={{ color: s.color }}>{s.name}</b> · {labels[i]} · {fmtY(s.data[i])}</span>);
        return (
          <g key={si}>
            {area && s.fill !== false && <path d={fillPath} fill={s.color} opacity="0.12" />}
            <path d={line} fill="none" stroke={s.color} strokeWidth={s.width ?? 2} strokeDasharray={s.dash ?? "0"} strokeLinejoin="round" strokeLinecap="round" />
            {s.dots !== false && s.data.map((v, i) => (
              <circle key={i} cx={x(i)} cy={y(v)} r={s.dotR ?? 2.4} fill={s.color}
                style={{ cursor: tip ? "pointer" : "default" }}
                onMouseEnter={(e) => show(e, i)} onMouseMove={(e) => show(e, i)} />
            ))}
          </g>
        );
      })}
    </svg>
  );
}

// ── grouped / stacked bars ──────────────────────────────────────────────────
export interface BarGroup { name: string; color: string; data: number[] }
interface BarsProps {
  groups: BarGroup[];
  labels: string[];
  height?: number;
  stacked?: boolean;
  fmtY?: (v: number) => ReactNode;
  tip?: ChartTip;
}
export function Bars({ groups, labels, height = 130, stacked = false, fmtY = (v) => v, tip }: BarsProps) {
  const W = 720, H = height, PAD = { l: 30, r: 12, t: 10, b: 22 };
  const iw = W - PAD.l - PAD.r, ih = H - PAD.t - PAD.b;
  const n = labels.length;
  const seriesCount = groups.length;
  const max = stacked
    ? Math.max(1, ...labels.map((_, i) => groups.reduce((s, g) => s + g.data[i], 0)))
    : Math.max(1, ...groups.flatMap(g => g.data));
  const slot = iw / n;
  const y = (v: number) => PAD.t + (1 - v / max) * ih;
  const bw = stacked ? Math.min(26, slot * 0.5) : Math.min(13, (slot * 0.7) / seriesCount);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", display: "block" }} onMouseLeave={() => tip?.hide()}>
      {[0, 0.5, 1].map((t, i) => {
        const v = Math.round(max * t);
        return <g key={i}><line x1={PAD.l} y1={y(v)} x2={W - PAD.r} y2={y(v)} stroke="var(--border-soft)" strokeDasharray="2 3" />
          <text x={PAD.l - 4} y={y(v) + 3} textAnchor="end" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{fmtY(v)}</text></g>;
      })}
      {labels.map((lab, i) => {
        const cx = PAD.l + slot * i + slot / 2;
        return (
          <g key={i}>
            {groups.map((g, gi) => {
              const v = g.data[i];
              const h = (v / max) * ih;
              // Stacked offset = sum of preceding groups at this label (no mutation).
              const below = groups.slice(0, gi).reduce((a, gg) => a + gg.data[i], 0);
              let bx: number, by: number;
              if (stacked) { bx = cx - bw / 2; by = y(below + v); }
              else { bx = cx - (bw * seriesCount + 2 * (seriesCount - 1)) / 2 + gi * (bw + 2); by = y(v); }
              return <rect key={gi} x={bx} y={by} width={bw} height={Math.max(0, h)} rx="1.5" fill={g.color}
                style={{ cursor: tip ? "pointer" : "default" }}
                onMouseMove={(e) => tip?.show(e.clientX, e.clientY, <span><b style={{ color: g.color }}>{g.name}</b> · {lab} · {fmtY(v)}</span>)} />;
            })}
            <text x={cx} y={H - PAD.b + 13} textAnchor="middle" fontFamily="var(--mono)" fontSize="8.5" fill="var(--fg-dim)">{lab}</text>
          </g>
        );
      })}
    </svg>
  );
}

// ── donut / gauge ───────────────────────────────────────────────────────────
export interface DonutSlice { name: string; value: number; color: string }
interface DonutProps { slices: DonutSlice[]; size?: number; thickness?: number; center?: { value: ReactNode; label: string } }
export function Donut({ slices, size = 132, thickness = 16, center }: DonutProps) {
  const r = (size - thickness) / 2, cx = size / 2, cy = size / 2;
  const C = 2 * Math.PI * r;
  const total = slices.reduce((s, x) => s + x.value, 0) || 1;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke="var(--bg-elev2)" strokeWidth={thickness} />
      {slices.map((s, i) => {
        const frac = s.value / total;
        const dash = frac * C;
        // Cumulative offset of preceding slices (no render-time mutation).
        const before = slices.slice(0, i).reduce((a, x) => a + x.value, 0) / total;
        return <circle key={i} cx={cx} cy={cy} r={r} fill="none" stroke={s.color}
          strokeWidth={thickness} strokeDasharray={`${dash} ${C - dash}`}
          strokeDashoffset={-before * C} transform={`rotate(-90 ${cx} ${cy})`}><title>{s.name}: {s.value}</title></circle>;
      })}
      {center && <>
        <text x={cx} y={cy - 2} textAnchor="middle" fontFamily="var(--mono)" fontSize="20" fontWeight="700" fill="var(--fg)">{center.value}</text>
        <text x={cx} y={cy + 14} textAnchor="middle" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{center.label}</text>
      </>}
    </svg>
  );
}

// ── horizontal bars (ranked) ─────────────────────────────────────────────────
export interface HBarRow {
  label: string;
  value: number;
  color?: string;
  strong?: boolean;
  icon?: ReactNode;
  tag?: ReactNode;
}
interface HBarsProps { rows: HBarRow[]; fmtV?: (v: number) => ReactNode; max?: number }
export function HBars({ rows, fmtV = (v) => v, max: maxOverride }: HBarsProps) {
  const max = maxOverride ?? Math.max(1, ...rows.map(r => r.value));
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
      {rows.map((r, i) => (
        <div key={i} className="hrow" style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) 46px", gap: 10, alignItems: "center", padding: "1px 2px", borderRadius: 4 }}>
          <div style={{ minWidth: 0 }}>
            <div className="mono" style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 3, fontSize: 10.5, color: "var(--fg-muted)" }}>
              {r.icon}
              <span style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", color: r.strong ? "var(--fg)" : undefined }}>{r.label}</span>
              {r.tag}
            </div>
            <div className="meter" style={{ height: 6 }}>
              <i style={{ width: `${(r.value / max) * 100}%`, background: r.color ?? "var(--accent)" }} />
            </div>
          </div>
          <div className="mono" style={{ textAlign: "right", fontSize: 11, color: "var(--fg)" }}>{fmtV(r.value)}</div>
        </div>
      ))}
    </div>
  );
}

// ── swimlane / activity timeline ─────────────────────────────────────────────
export interface SwimLane { name: string; color?: string }
export interface SwimEvent { lane: number; t0: number; t1?: number; color: string; label: string; r?: number }
export interface SwimMark { t: number; label: string }
interface SwimlaneProps { lanes: SwimLane[]; events: SwimEvent[]; height?: number; tip?: ChartTip; marks?: SwimMark[] }
export function Swimlane({ lanes, events, height = 26, tip, marks = [] }: SwimlaneProps) {
  const W = 720, laneH = height, top = 16, left = 96, right = 14;
  const iw = W - left - right;
  const H = top + lanes.length * laneH + 6;
  const xt = (t: number) => left + t * iw;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", display: "block" }} onMouseLeave={() => tip?.hide()}>
      {marks.map((m, i) => (
        <g key={`mk${i}`}>
          <line x1={xt(m.t)} y1={top - 4} x2={xt(m.t)} y2={H - 4} stroke="var(--border-soft)" strokeDasharray="2 4" />
          <text x={xt(m.t)} y={top - 6} textAnchor="middle" fontFamily="var(--mono)" fontSize="8" fill="var(--fg-dim)">{m.label}</text>
        </g>
      ))}
      {lanes.map((ln, li) => {
        const cy = top + li * laneH + laneH / 2;
        return (
          <g key={li}>
            <text x={left - 8} y={cy + 3} textAnchor="end" fontFamily="var(--mono)" fontSize="9.5" fill={ln.color ?? "var(--fg-muted)"}>{ln.name}</text>
            <line x1={left} y1={cy} x2={W - right} y2={cy} stroke="var(--border-soft)" strokeWidth="1" />
          </g>
        );
      })}
      {events.map((e, i) => {
        const cy = top + e.lane * laneH + laneH / 2;
        if (e.t1 != null) {
          const x0 = xt(e.t0), x1 = xt(e.t1);
          return <rect key={i} x={x0} y={cy - 4} width={Math.max(3, x1 - x0)} height={8} rx="3" fill={e.color} opacity="0.85"
            style={{ cursor: tip ? "pointer" : "default" }}
            onMouseMove={(ev) => tip?.show(ev.clientX, ev.clientY, <span>{e.label}</span>)} />;
        }
        return <circle key={i} cx={xt(e.t0)} cy={cy} r={e.r ?? 4} fill={e.color} stroke="var(--bg-panel)" strokeWidth="1.5"
          style={{ cursor: tip ? "pointer" : "default" }}
          onMouseMove={(ev) => tip?.show(ev.clientX, ev.clientY, <span>{e.label}</span>)} />;
      })}
    </svg>
  );
}

// ── inline sparkline ─────────────────────────────────────────────────────────
interface SparkProps { data: number[]; color: string; w?: number; h?: number; fill?: boolean; dot?: boolean }
export function Spark({ data, color, w = 70, h = 20, fill = true, dot = true }: SparkProps) {
  if (data.length < 2) return null;
  const max = Math.max(1, ...data), min = Math.min(...data);
  const span = max - min || 1;
  const x = (i: number) => (i / (data.length - 1)) * w;
  const y = (v: number) => h - 2 - ((v - min) / span) * (h - 4);
  const line = data.map((v, i) => `${i === 0 ? "M" : "L"} ${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(" ");
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ display: "block" }}>
      {fill && <path d={`${line} L ${w} ${h} L 0 ${h} Z`} fill={color} opacity="0.13" />}
      <path d={line} fill="none" stroke={color} strokeWidth="1.6" strokeLinejoin="round" strokeLinecap="round" />
      {dot && <circle cx={x(data.length - 1)} cy={y(data[data.length - 1])} r="2" fill={color} />}
    </svg>
  );
}

// ── stacked daily bars (over-time) card ───────────────────────────────────────
// A panel-wrapped, two-series stacked bar chart over a fixed run of days — the shared
// "Calls/Fires over time" card on the MCP + Hook analytics tabs (#1740). `lower` stacks
// at the baseline, `upper` on top of it. Day labels show every 3rd bucket.
export interface StackedDay { day: string; upper: number; lower: number }
export function StackedDayBars({
  data, title, subtitle, upperLabel, lowerLabel,
  upperColor = "var(--accent)", lowerColor = "var(--danger)",
}: {
  data: StackedDay[];
  title: string;
  subtitle: string;
  upperLabel: string;
  lowerLabel: string;
  upperColor?: string;
  lowerColor?: string;
}) {
  const W = 600, H = 160, x0 = 30, baseY = 140, topY = 12;
  const n = data.length || 1;
  const maxTotal = Math.max(1, ...data.map((d) => d.lower + d.upper));
  const bw = (W - x0 - 10) / n;
  const scaleY = (v: number) => (v / maxTotal) * (baseY - topY);
  const gridVals = [0, Math.ceil(maxTotal / 2), maxTotal];
  return (
    <div style={{ background: "var(--bg-panel)", border: "1px solid var(--border-soft)", borderRadius: 8, padding: "14px 16px", marginBottom: 10 }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 10 }}>
        <h3 className="mono" style={{ margin: 0, fontSize: 11, color: "var(--fg)", fontWeight: 600 }}>{title}</h3>
        <span style={{ fontSize: 10.5, color: "var(--fg-dim)" }}>{subtitle}</span>
        <div style={{ flex: 1 }} />
        <span className="mono" style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 10, color: "var(--fg-muted)" }}><span style={{ width: 9, height: 9, borderRadius: 2, background: upperColor }} />{upperLabel}</span>
        <span className="mono" style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 10, color: "var(--fg-muted)" }}><span style={{ width: 9, height: 9, borderRadius: 2, background: lowerColor }} />{lowerLabel}</span>
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} className="mono" style={{ width: "100%", height: "auto", display: "block" }}>
        {gridVals.map((v, i) => {
          const y = baseY - scaleY(v);
          return (
            <g key={i}>
              <line x1={x0} y1={y} x2={W - 8} y2={y} stroke="var(--border-soft)" strokeWidth={1} />
              <text x={x0 - 6} y={y + 3} textAnchor="end" fill="var(--fg-dim)" fontSize={9}>{v}</text>
            </g>
          );
        })}
        {data.map((d, i) => {
          const x = x0 + 4 + i * bw;
          const w = bw - 5;
          const hLower = scaleY(d.lower);
          const hUpper = scaleY(d.upper);
          const yLower = baseY - hLower;
          const yUpper = yLower - hUpper;
          const showLabel = i % 3 === 0;
          return (
            <g key={i}>
              {hLower > 0 && <rect x={x} y={yLower} width={w} height={hLower} rx={2} fill={lowerColor} />}
              {hUpper > 0 && <rect x={x} y={yUpper} width={w} height={hUpper} rx={2} fill={upperColor} />}
              {showLabel && <text x={x + w / 2} y={152} textAnchor="middle" fill="var(--fg-dim)" fontSize={8.5}>{d.day.slice(5)}</text>}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

// ── legend ──────────────────────────────────────────────────────────────────
export interface LegendItem { color: string; label: string; value?: ReactNode }
export function Legend({ items, style }: { items: LegendItem[]; style?: React.CSSProperties }) {
  return (
    <div className="mono" style={{ display: "flex", gap: 14, flexWrap: "wrap", fontSize: 10, color: "var(--fg-muted)", ...style }}>
      {items.map((it, i) => (
        <span key={i} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
          <span style={{ width: 9, height: 9, borderRadius: 2, background: it.color, display: "inline-block" }} />
          {it.label}{it.value != null && <b style={{ color: "var(--fg)" }}>{it.value}</b>}
        </span>
      ))}
    </div>
  );
}

// Shared analytics card + control primitives (#399), ported from
// design/fleet-github-skills/js/shell.jsx. Used alongside the SVG charts on the
// Fleet / Repo Pulse analytics pages.

/** Compact number formatter (e.g. 1234 → "1.2k", 12000 → "12k"). */
export function fmt(n: number): string {
  return n >= 1000 ? (n / 1000).toFixed(n >= 10000 ? 0 : 1) + "k" : String(n);
}

export type StatTone = "fg" | "accent" | "info" | "success" | "danger";
interface StatCardProps {
  k: string;
  v: ReactNode;
  sub?: ReactNode;
  tone?: StatTone;
  delta?: { dir: "up" | "down" | "flat"; text: string };
  /** Render the value (and sub) as shimmer placeholders while the metric's source loads (#2234). */
  loading?: boolean;
}
export function StatCard({ k, v, sub, tone, delta, loading }: StatCardProps) {
  const color =
    tone === "accent" ? "var(--accent)" : tone === "info" ? "var(--info)" :
    tone === "success" ? "var(--success)" : tone === "danger" ? "var(--danger)" : "var(--fg)";
  return (
    <div className="card statcard">
      <div className="k">{k}</div>
      {loading
        ? <div className="v"><Skeleton h={20} w={56} radius={5} style={{ margin: "3px 0" }} /></div>
        : <div className="v" style={{ color }}>{v}</div>}
      <div className="sub">
        {loading ? <Skeleton h={9} w={72} radius={4} /> : (<>
          {delta && <span className={`delta ${delta.dir}`}>{delta.dir === "up" ? "▲" : delta.dir === "down" ? "▼" : "■"} {delta.text}</span>}
          {sub}
        </>)}
      </div>
    </div>
  );
}

export function CardHead({ title, hint, right }: { title: string; hint?: ReactNode; right?: ReactNode }) {
  return (
    <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 12 }}>
      <h3 style={{ margin: 0 }}>{title}</h3>
      {hint && <span className="hint">{hint}</span>}
      <div style={{ flex: 1 }} />
      {right}
    </div>
  );
}

/** Time-range segmented control. */
export function RangeToggle({ value, onChange, options = ["7d", "14d", "30d"] }: {
  value: string;
  onChange: (v: string) => void;
  options?: string[];
}) {
  return (
    <div className="seg">
      {options.map(o => (
        <button key={o} className={o === value ? "on" : ""} onClick={() => onChange(o)}>{o}</button>
      ))}
    </div>
  );
}

/** A small agent/user avatar; `bot` renders a rounded-square agent glyph. */
: { login: string; size?: number; bot?: boolean }) {
  const color = bot ? "oklch(0.78 0.14 70)" : loginColor(login);
  return (
    <span title={login} className="mono" style={{
      width: size, height: size, borderRadius: bot ? size * 0.28 : "50%",
      background: color, color: "#1a120a",
      fontWeight: 700, fontSize: size * 0.46,
      display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
    }}>
      {bot ? "◆" : (login.replace(/^@/, "")[0]?.toUpperCase() ?? "?")}
    </span>
  );
}

/** A lightweight hover-tooltip controller for the charts. Render `node` once
 *  near the page root; pass the handle to a chart's `tip` prop. */
export function useTip(): ChartTip & { node: ReactNode } {
  const [tip, setTip] = useState<{ x: number; y: number; content: ReactNode } | null>(null);
  const show = useCallback((x: number, y: number, content: ReactNode) => setTip({ x, y, content }), []);
  const hide = useCallback(() => setTip(null), []);
  const tipStyle: CSSProperties = tip
    ? { left: tip.x, top: tip.y, transform: "translate(-50%,-120%)" }
    : {};
  const node = tip ? <div className="chart-tip" style={tipStyle}>{tip.content}</div> : null;
  return { show, hide, node };
}

// Telemetry-tab primitives (#1826) — the framed panel + the two bar shapes the analytics tabs
// (McpAnalytics, HookAnalytics, …) were copy-pasting. Composed with the existing chart primitives
// (StatCard / StackedDayBars) each tab already uses; each tab keeps its own top-level layout and
// any bespoke bits (a results log, a legend) as local JSX, so there are no awkward optional slots.

/** A framed analytics panel: `bg-panel` card + a baseline header (title · optional hint · optional
 *  right-aligned slot). The repeated `<div class card><h3>…</h3></div>` wrapper. */
export function TelemetryPanel({ title, hint, right, children }: {
  title: string;
  hint?: string;
  /** Right-aligned header content (a legend, a filter, a count) — a spacer is inserted before it. */
  right?: ReactNode;
  children: ReactNode;
}) {
  return (
    <div style={{ background: "var(--bg-panel)", border: "1px solid var(--border-soft)", borderRadius: 8, padding: "14px 16px" }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 14 }}>
        <h3 className="mono" style={{ margin: 0, fontSize: 11, color: "var(--fg)", fontWeight: 600 }}>{title}</h3>
        {hint && <span style={{ fontSize: 10.5, color: "var(--fg-dim)" }}>{hint}</span>}
        {right != null && <><div style={{ flex: 1 }} />{right}</>}
      </div>
      {children}
    </div>
  );
}

/** One row of {@link ItemBars}: a label · optional meta · a right-aligned value over a {@link FillBar}. */
export interface ItemBarRow {
  key: string;
  label: string;
  meta?: string;
  /** The value shown at the right of the row (formatted string or number). */
  value: ReactNode;
  /** The bar fill fraction, 0..1. */
  fraction: number;
  /** Bar color (defaults to the FillBar accent). */
  color?: string;
}

/** A vertical list of labelled `FillBar` rows (Calls-per-server, Fires-per-hook, …). */
export function ItemBars({ rows, empty }: { rows: ItemBarRow[]; empty?: ReactNode }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 13 }}>
      {rows.length === 0 && (empty ?? <span className="hint">No data recorded yet.</span>)}
      {rows.map((r) => (
        <div key={r.key}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginBottom: 5 }}>
            <span className="mono" style={{ fontSize: 11, color: "var(--fg)" }}>{r.label}</span>
            {r.meta && <span className="mono" style={{ fontSize: 9.5, color: "var(--fg-dim)" }}>{r.meta}</span>}
            <div style={{ flex: 1 }} />
            <span className="mono" style={{ fontSize: 11, color: "var(--fg-muted)" }}>{r.value}</span>
          </div>
          <FillBar value={r.fraction} color={r.color} />
        </div>
      ))}
    </div>
  );
}

/** A two-segment proportional bar with a label + the two counts (ok/err, allow/block, …). */
export function SplitBar({ label, a, b, aLabel, bLabel, aColor = "var(--success)", bColor = "var(--danger)" }: {
  label: string;
  a: number;
  b: number;
  aLabel: string;
  bLabel: string;
  aColor?: string;
  bColor?: string;
}) {
  const tot = Math.max(1, a + b);
  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginBottom: 5 }}>
        <span className="mono" style={{ fontSize: 11, color: "var(--fg)" }}>{label}</span>
        <div style={{ flex: 1 }} />
        <span className="mono" style={{ fontSize: 10, color: aColor }}>{a} {aLabel}</span>
        <span className="mono" style={{ fontSize: 10, color: bColor }}>{b} {bLabel}</span>
      </div>
      <div style={{ height: 10, borderRadius: 99, overflow: "hidden", display: "flex", background: "var(--bg-elev2)" }}>
        <div style={{ height: "100%", width: `${(a / tot) * 100}%`, background: aColor }} />
        <div style={{ height: "100%", width: `${(b / tot) * 100}%`, background: bColor }} />
      </div>
    </div>
  );
}
